import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listCommentsHandler } from "../handlers/listCommentsHandler";
import type { ApiError } from "../runtime/client";
import type { FeedPartition } from "../types/FeedPartition";
import type { PostCommentEntityType } from "../types/PostCommentEntityType";

type Data = Awaited<ReturnType<typeof listCommentsHandler>>;

export function useListCommentsHandler(
  postId: FeedPartition,
  commentId: PostCommentEntityType,
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listCommentsHandler", postId, commentId, bookmark],
    queryFn: () => listCommentsHandler(postId, commentId, bookmark),
    ...options,
  });
}
